(function () {
'use strict';
function bootLocaboWaterPuzzle() {
const root = document.querySelector('main.app');
if (!root || !root.querySelector('#content') || root.dataset.locaboBooted === 'true') return;
root.dataset.locaboBooted = 'true';
'use strict';
const CONFIG={duration:20,intro:6,explainStep:3.5,url:'https://locabo.online/lp/locv198_02/index.html?sb_tracking=true'};
const content=document.getElementById('content');
const REWARD_KEY='locabo-water-puzzle:GOHAN2000:v1';
function savedReward(){try{return localStorage.getItem(REWARD_KEY)==='earned'}catch{return false}}
function saveReward(){try{localStorage.setItem(REWARD_KEY,'earned')}catch{}}

let phase='intro',board=[],solution=[],route=[0,4,5,6,10,14,15],moves=0,score=0,left=4,paused=false,step=0,elapsed=0,last=performance.now(),assisted=false,hintIndex=-1,idle=0,round=0,screenEntered=0,couponEarned=savedReward(),roundWon=false,started=false;
const edges=[[0,-1],[1,0],[0,1],[-1,0]];
function event(name,detail={}){window.dispatchEvent(new CustomEvent('locabo:'+name,{detail}));window.dataLayer?.push({event:'locabo_'+name,...detail})}
function rotate(mask){return ((mask<<1)&15)|(mask>>3)}
function neighbor(i,d){const x=i%4+edges[d][0],y=Math.floor(i/4)+edges[d][1];return x<0||x>3||y<0||y>3?-1:y*4+x}
function trace(){if(!(board[0]&1))return [];let seen=new Set([0]),q=[0];while(q.length){const i=q.shift();for(let d=0;d<4;d++){if(!(board[i]&(1<<d)))continue;const j=neighbor(i,d);if(j>=0&&(board[j]&(1<<((d+2)%4)))&&!seen.has(j)){seen.add(j);q.push(j)}}}return [...seen]}
function solved(){return trace().includes(15)&&!!(board[15]&4)}
function newBoard(){round++;route=[0,4,5,6,10,14,15];board=[5,10,6,12,3,10,12,5,6,9,5,3,9,10,3,12];solution=board.slice();for(const i of [4,6,14,15]){board[i]=rotate(rotate(rotate(solution[i])));} }
function enterScreen(next){phase=next;paused=false;left=0;last=performance.now();screenEntered=last;document.getElementById('pauseLayer').hidden=true;document.querySelector('.app')?.classList.remove('paused');content.scrollTop=0;window.scrollTo?.({top:0,behavior:'instant'})}
function ready(){return performance.now()-screenEntered>500}
function progress(n){document.querySelectorAll('.steps span').forEach((x,i)=>x.classList.toggle('active',i===n));document.getElementById('pause').hidden=['cta','explain','result','reward'].includes(phase)}
function cooker(right){return `<div class="cooker-scene ${right?'black-cooker':'white-cooker'}"><div class="steam-clouds" aria-hidden="true"><i></i><i></i><i></i></div><div class="cooker-art" role="img" aria-label="${right?'LOCABOをイメージした黒い炊飯器':'白い一般的な炊飯器'}"></div><div class="heat-halo"></div><div class="heat-dots" aria-hidden="true">● ● ●</div></div><div class="mini-section" aria-label="水の行き先の模式図"><span class="rice-level">ごはん</span><span class="water-level">${right?'外釜へ分離':'釜の中で炊飯'}</span></div>`}
function pipe(mask,wet,entry=0){const ends=[0,1,2,3].filter(d=>mask&(1<<d)).sort((a,b)=>(b===entry)-(a===entry)),p=[[40,0],[80,40],[40,80],[0,40]],a=p[ends[0]],b=p[ends[1]],d=`M${a[0]} ${a[1]} Q40 40 ${b[0]} ${b[1]}`;return `<svg viewBox="0 0 80 80" aria-hidden="true"><path d="${d}" fill="none" stroke="#173b39" stroke-width="38"/><path d="${d}" fill="none" stroke="#d8ece1" stroke-width="32"/><path d="${d}" fill="none" stroke="${wet?'#32b8ed':'#71968c'}" stroke-width="22"/>${wet?`<path d="${d}" class="water-flow" fill="none" stroke="#effcff" stroke-width="3" stroke-dasharray="2 18" stroke-linecap="round"/>`:''}</svg>`}
function frontier(){const wet=trace();for(const i of wet){for(let d=0;d<4;d++){if(!(board[i]&(1<<d)))continue;const j=neighbor(i,d);if(j<0){if((i===0&&d===0)||(i===15&&d===2))continue;return {i,d};}if(!(board[j]&(1<<((d+2)%4))))return {i,d};}}return null}
function renderBoard(){const focusIndex=document.activeElement?.dataset?.index,flow=trace(),wet=new Set(flow),end=frontier();const el=document.getElementById('board');if(!el)return;el.innerHTML=board.map((m,i)=>`<button class="pipe-tile ${wet.has(i)?'wet':''} ${i===hintIndex?'hint':''}" data-index="${i}" aria-label="${Math.floor(i/4)+1}行${i%4+1}列。${[0,1,2,3].filter(d=>m&(1<<d)).map(d=>['上','右','下','左'][d]).join('と')}につながる管。タップで右回転" ${phase==='flow'?'disabled':''}>${pipe(m,wet.has(i),i===0?0:edges.findIndex((_,d)=>neighbor(i,d)===flow[flow.indexOf(i)-1]))}${end?.i===i&&phase!=='flow'?`<i class="water-tip tip-${end.d}" aria-hidden="true"></i>`:''}${i===hintIndex?'<span class="tap-hand" aria-hidden="true">☝</span>':''}</button>`).join('');el.onclick=e=>{const b=e.target.closest('[data-index]');if(b)tap(Number(b.dataset.index))};if(focusIndex!=null)el.querySelector(`[data-index="${focusIndex}"]`)?.focus({preventScroll:true});}
function grains(cx,cy,count=19){return Array.from({length:count},(_,i)=>{const row=Math.floor(i/7),x=cx+(i%7-3)*11+(row%2)*3,y=cy-row*8;return `<ellipse cx="${x}" cy="${y}" rx="7" ry="3.6" transform="rotate(${i%2?25:-20} ${x} ${y})" fill="#fffdf1" stroke="#c8d3bc" stroke-width=".7"/>`}).join('')}
function potScene(){return `<svg viewBox="0 0 350 112" role="img" aria-label="内釜のお米。水を含んでふくらみ、接続後に水位が下がって蒸し上がります"><defs><linearGradient id="potSteel" x2="0" y2="1"><stop stop-color="#aec6b8"/><stop offset="1" stop-color="#446757"/></linearGradient></defs><path d="M65 34H285L271 92Q175 112 79 92Z" fill="url(#potSteel)" stroke="#c8d9c9" stroke-width="2"/><ellipse cx="175" cy="36" rx="110" ry="18" fill="#173e32" stroke="#d0dfcd" stroke-width="3"/><g class="inner-water"><ellipse cx="175" cy="40" rx="101" ry="14" fill="#87d5f0" opacity=".8"/></g><g class="cooking-grains"><image href="https://ichinose-pixel.github.io/locabo-water-puzzle/rice-mound.webp" x="91" y="1" width="168" height="57" preserveAspectRatio="none"/></g><g class="pot-steam" fill="none" stroke="#faf9e5" stroke-width="3" stroke-linecap="round"><path d="M125 28q-12-9 0-20t0-18"/><path d="M175 27q-12-9 0-20t0-18"/><path d="M225 28q-12-9 0-20t0-18"/></g><text x="175" y="80" fill="#fff8de" text-anchor="middle" font-size="13">内釜のお米</text></svg>`}
function start(){enterScreen('intro');score=moves=elapsed=0;roundWon=false;left=CONFIG.intro;paused=assisted=false;hintIndex=4;idle=0;newBoard();progress(0);content.innerHTML=`<section class="opening-screen gift-opening"><h1 class="gift-headline"><span class="gift-condition">ゲームクリアで</span><span class="gift-prize">特別クーポン<span class="gift-get">GET!</span></span></h1><div class="gift-visual"><img src="data:image/webp;base64," width="960" height="640" alt="リボン付きの金色の特別クーポン！" fetchpriority="high" decoding="sync"></div><div class="puzzle-invitation"><div class="puzzle-invite-copy"><p>炊飯器の水を流せ！</p><h2>水路パズル</h2></div><div class="puzzle-preview"><svg viewBox="0 0 112 68" aria-hidden="true"><defs><linearGradient id="preview-water" x2="1" y2="1"><stop stop-color="#dcfbff"/><stop offset="1" stop-color="#39b9ee"/></linearGradient></defs><rect x="1" y="1" width="110" height="66" rx="12" fill="#102e29" stroke="#ffffff30"/><path d="M22 0V33H89V68" fill="none" stroke="#9aae9e" stroke-width="22" stroke-linejoin="round"/><path d="M22 0V33H89V68" fill="none" stroke="#123b39" stroke-width="15" stroke-linejoin="round"/><path d="M22 0V33H89V68" fill="none" stroke="url(#preview-water)" stroke-width="9" stroke-linejoin="round"/><path class="preview-flow" d="M22 0V33H89V68" fill="none" stroke="#fff" stroke-width="3" stroke-dasharray="3 18" stroke-linecap="round"/><path d="M56 5v57" stroke="#071f19" stroke-width="4"/><circle cx="10" cy="10" r="2" fill="#d9c78b"/><circle cx="102" cy="58" r="2" fill="#d9c78b"/></svg></div></div><p class="gift-operation">タップで回して、出口までつなごう</p><div class="gift-start"><span>まもなくスタート</span><b id="count">${CONFIG.intro}</b><i aria-hidden="true"></i></div></section>`;event('intro')}
function renderGame(){content.innerHTML=`<section class="race immersive-game intuitive-game" data-version="intuitive-v2"><div class="game-heading"><b>水路パズル</b><span id="timer">まずは1タップ</span></div><h1 class="play-goal">水路を回して、<em>右下へ流そう！</em></h1><div class="play-coach"><strong id="instruction" role="status">光るパネルをタップで回す</strong><button id="hint" class="hint-button">ヒント</button></div><div class="pipe-area"><div class="source-unit"><div class="inner-pot">${potScene()}</div><div class="source-copy"><b>ここから ↓</b><span id="pot-caption">炊飯中の水</span></div><div class="source-neck" aria-hidden="true"></div></div><div class="board-frame"><div id="board" class="pipe-board" aria-label="4行4列の流路パズル"></div></div><div class="sink-unit"><div class="sink-neck" aria-hidden="true"></div><div class="outer-pot"><div class="collected-water"></div><b id="collect-caption">ここまで流せばクリア！</b><span>外釜</span></div></div></div><p class="race-note">流路・吸水・蒸し上げを簡略化したイメージです。<br>実際の構造・炊飯時間・体積変化の割合は表しません。</p></section>`;document.getElementById('hint').onclick=showHint;renderBoard();requestAnimationFrame(fitBoard)}
function fitBoard(){const area=document.querySelector('.pipe-area');if(!area)return;area.style.width='';const available=area.getBoundingClientRect().width;const screen=content.querySelector('section');const overflow=Math.max(0,screen.scrollHeight-content.clientHeight);area.style.width=Math.max(192,available-overflow-3)+'px'}
window.addEventListener('resize',()=>requestAnimationFrame(fitBoard));
function begin(){phase='playing';last=performance.now();left=CONFIG.duration;started=false;hintIndex=4;renderGame();event('game_start')}
function tap(i){if(!Number.isInteger(i)||i<0||i>15)throw Error('マスは0〜15で指定してください');if(!['playing','assist'].includes(phase)||paused)return {accepted:false};const before=trace().length;board[i]=rotate(board[i]);moves++;idle=0;hintIndex=-1;if(!started&&trace().length>2){started=true;left=CONFIG.duration;document.getElementById('timer').textContent='残り20秒';}if(!started)hintIndex=4;renderBoard();document.querySelector(`[data-index="${i}"]`)?.classList.add('turned');if(solved())complete(false);else{document.getElementById('instruction').textContent=!started?'光るパネルをタップで回す':trace().length>before?'いいね！ 水の続きをつなごう':'水の先から、右下の出口へ';if(phase==='assist')showHint();}event('pipe_rotate',{index:i,moves});return {accepted:true,moves,solved:solved()}}
function showHint(){if(!['playing','assist'].includes(phase)||paused)return;hintIndex=route.find(i=>board[i]!==solution[i])??-1;renderBoard();document.getElementById('instruction').textContent=hintIndex>=0?'光るパネルをタップで回す':'右下の出口へつなごう'}
function complete(auto){if(!['playing','assist'].includes(phase)||auto)return;roundWon=true;couponEarned=true;saveReward();enterScreen('flow');left=3.6;hintIndex=-1;renderBoard();document.querySelector('.race')?.classList.add('cleared');document.getElementById('instruction').textContent='クリア！ 水が外釜へ流れた！';document.getElementById('pot-caption').textContent='ふっくら炊き上がり！';document.getElementById('collect-caption').textContent='特別クーポンGET！';document.getElementById('timer').textContent='接続成功 ✓';document.getElementById('hint').hidden=true;event('game_complete',{moves,assisted,seconds:Math.round(elapsed)})}
function timeout(){phase='assist';assisted=true;left=0;document.getElementById('timer').textContent='ヒントで続けよう';document.getElementById('timer').classList.remove('urgent');showHint();event('game_timeout')}
function result(){if(roundWon)celebrate();else explain(0)}
function celebrate(){enterScreen('reward');left=5.5;progress(1);content.innerHTML=`<section class="reward-screen"><div class="confetti" aria-hidden="true">${Array.from({length:26},(_,i)=>`<i style="--x:${(i*37)%100}%;--delay:${(i%7)*.11}s;--spin:${i%2?400:-350}deg;--color:${['#efce81','#87d9c1','#fff6d2'][i%3]}"></i>`).join('')}</div><p class="reward-top">GAME CLEAR!</p><h1>クリアおめでとう！</h1><p class="reward-lead">あなたに、特別なプレゼント。</p><div class="reward-ticket"><span class="ticket-kicker">クリア特典</span><h2 class="ticket-title">特別クーポン<br><b>GET!</b></h2><div class="win-coupon-value"><span>特別価格から、さらに</span><strong>2,000円OFF</strong></div></div><p class="reward-message">毎日のごはんを楽しむ一台を、<br><strong>あなたには、もっとお得に。</strong></p><button class="primary" id="reward-next">商品の仕組みを見る →</button><p class="note">2,000円OFFクーポンは獲得済みです。<br>クーポンコードは商品画面で確認できます。</p></section>`;document.getElementById('reward-next').onclick=()=>{if(phase==='reward'&&ready())explain(0)};event('coupon_earned',{code:'GOHAN2000'})}
function riceBowl(x){return `<image href="https://ichinose-pixel.github.io/locabo-water-puzzle/rice-bowl.webp" x="${x-53}" y="216" width="106" height="75" preserveAspectRatio="xMidYMid meet"/>`}

function diagram(n){if(n===0)return `<svg viewBox="0 0 360 270" role="img" aria-label="炊飯中に水位が下がり、内釜のお米を蒸し上げる模式図"><defs><linearGradient id="steel" x2="1" y2="1"><stop stop-color="#acc4b6"/><stop offset=".45" stop-color="#f0f4e8"/><stop offset="1" stop-color="#73988b"/></linearGradient><linearGradient id="aqua" x2="0" y2="1"><stop stop-color="#a3e2f5"/><stop offset="1" stop-color="#65bddf"/></linearGradient></defs><path class="heated-pot" d="M34 65V207Q34 239 69 239H279Q312 239 312 207V65" fill="none" stroke="#e98842" stroke-width="12" opacity=".55"/><path d="M44 42V204Q44 230 70 230H275Q302 230 302 204V42" fill="#d9e4d8" stroke="url(#steel)" stroke-width="12"/><path class="mechanism-water" d="M56 135Q87 125 122 135T188 135T254 135T290 135V202Q290 218 274 218H73Q56 218 56 202Z" fill="url(#aqua)"/><path d="M81 57V140Q81 155 96 155H250Q265 155 265 140V57" fill="#fffdf1" stroke="#668f7c" stroke-width="5"/><path d="M91 152H254" stroke="#eef5de" stroke-width="6" stroke-dasharray="6 9"/><g class="mechanism-steam" fill="none" stroke="#64a699" stroke-width="3" stroke-linecap="round"><path d="M119 72Q109 63 119 54T119 34"/><path d="M173 72Q163 63 173 54T173 34"/><path d="M227 72Q217 63 227 54T227 34"/></g><text x="173" y="93" text-anchor="middle" font-size="21" font-weight="bold" fill="#395c47">お米</text><text x="173" y="123" text-anchor="middle" font-size="14" fill="#6a8070">蒸気で蒸し上げる</text><g class="water-dot" fill="#f7fcff"><circle cx="114" cy="148" r="5"/><circle cx="172" cy="145" r="5"/><circle cx="231" cy="150" r="5"/></g><text x="173" y="190" text-anchor="middle" font-size="13" font-weight="bold" fill="#154f45">でんぷんの一部が</text><text x="173" y="209" text-anchor="middle" font-size="13" fill="#154f45">溶け出した水</text><g fill="none" stroke="#9c742b" stroke-width="4" stroke-linecap="round"><path d="M115 137V178m-6-7 6 7 6-7"/><path d="M231 137V178m-6-7 6 7 6-7"/></g><text x="173" y="257" text-anchor="middle" font-size="14" fill="#456c57">外釜を加熱し、蒸気で蒸し上げる</text></svg>`;return `<svg viewBox="0 0 360 345" role="img" aria-label="水を含むことで、ごはん一粒あたりの体積が増える模式図。拡大率は説明用"><defs><radialGradient id="grain"><stop stop-color="#fffef4"/><stop offset=".75" stop-color="#eeeeda"/><stop offset="1" stop-color="#c4d1b7"/></radialGradient></defs><circle cx="100" cy="112" r="69" fill="#e1e9da"/><circle cx="265" cy="112" r="83" fill="#cfe6d7"/><ellipse cx="100" cy="112" rx="23" ry="41" transform="rotate(25 100 112)" fill="url(#grain)" stroke="#a1b89e" stroke-width="2"/><g class="rice-expand"><ellipse cx="265" cy="112" rx="32" ry="55" transform="rotate(25 265 112)" fill="url(#grain)" stroke="#a1b89e" stroke-width="2"/></g><path d="M173 112H195M189 106L196 112L189 118" stroke="#799c85" stroke-width="3" fill="none"/><text x="100" y="207" text-anchor="middle" font-size="14" fill="#58745e">水を含む</text><text x="265" y="207" text-anchor="middle" font-size="14" font-weight="bold" fill="#2f654b">一粒あたりの体積が増加</text>${riceBowl(95)}${riceBowl(265)}<path d="M162 259H194m-6-6 6 6-6 6" fill="none" stroke="#628472" stroke-width="3"/><text x="180" y="303" text-anchor="middle" font-size="14" font-weight="bold" fill="#2f654b">同量を取り分けたごはんで、糖質量を比較</text><text x="180" y="328" text-anchor="middle" font-size="11" fill="#58745e">分離と体積増加による仕組みの模式図です。</text></svg>`}
function productSummary(){return `<div class="product-summary"><div class="summary-pair"><div><span>01</span><b>でんぷんの<br>一部を分離</b></div><i>＋</i><div><span>02</span><b>水を含んで<br>体積を増やす</b></div></div><div class="summary-connection" aria-hidden="true">↓</div><p class="summary-caption">2つの仕組みを、この一台に。</p><div class="summary-black"><img src="data:image/png;base64," alt="2つの仕組みを備えたLOCABO:V ブラック"></div><strong class="summary-brand">LOCABO:V</strong></div>`}
function explain(n){enterScreen('explain');step=Math.max(0,Math.min(2,n));left=6.5;progress(1);const data=[['水の行き先に、','炊き方の違い。','でんぷんの一部を含む水を<b>外釜へ分離。</b>炊飯が進むと水位が下がり、<b>蒸気でごはんを蒸し上げます。</b>'],['水を含んで、','ふっくら炊き上がる。','ごはん一粒あたりの体積が増加。分離とあわせて、<b>同量のごはんの糖質量を減らす</b>仕組みです。'],['ごはん好きの、','糖質対策。','でんぷんの一部分離と、ごはんの体積の増加。<b>2つの仕組みを、毎日の炊飯に。</b>']][step];content.innerHTML=`<section class="explain story-explain"><p class="eyebrow">炊き方のひみつ · ${step+1} / 3</p><h1>${data[0]}<br><em>${data[1]}</em></h1>${step<2?`<div class="diagram story-diagram">${diagram(step)}</div>`:productSummary()}<div class="dots" aria-label="説明${step+1}/3">${[0,1,2].map(i=>`<i class="${i===step?'on':''}"></i>`).join('')}</div><p class="explain-copy">${data[2]}</p><button class="primary" id="next">${step<2?'次へ →':couponEarned?'クーポンで商品を見る →':'特別価格の商品を見る →'}</button><div class="story-playback"><div class="story-timer"><i id="story-time"></i></div><button id="story-hold">一時停止</button></div><div class="story-controls">${step>0?'<button class="secondary" id="previous">ひとつ戻る</button>':'<span></span>'}<button class="secondary" id="skip-story">商品を見る</button></div><p class="mechanism-note">通常炊飯モードで炊いたごはんを同量取り分けた場合との比較です。炊飯量全体の比較ではありません。炊飯条件により結果は異なります。</p></section>`;const current=step;document.getElementById('story-hold').onclick=e=>{if(phase!=='explain'||step!==current)return;paused=!paused;e.target.textContent=paused?'自動再生を再開':'一時停止'};document.getElementById('next').onclick=()=>{if(phase!=='explain'||step!==current||!ready())return;current<2?explain(current+1):cta()};if(current>0)document.getElementById('previous').onclick=()=>{if(phase==='explain'&&step===current&&ready())explain(current-1)};document.getElementById('skip-story').onclick=()=>{if(phase==='explain'&&step===current&&ready())cta()};event('explanation_view',{step:step+1})}
function destination(){const url=new URL(CONFIG.url),incoming=new URLSearchParams(location.search),replaced=new Set();for(const [k,v] of incoming){if(k==='ad_code'||k==='sb_tracking')continue;if(!replaced.has(k)){url.searchParams.delete(k);replaced.add(k)}url.searchParams.append(k,v)}url.searchParams.delete('ad_code');url.searchParams.set('sb_tracking','true');return url.href}
async function copyCoupon(){if(phase!=='cta'||!couponEarned||!ready())return;const input=document.getElementById('coupon-code'),button=document.getElementById('copy-coupon'),message=document.getElementById('copy-status');try{await navigator.clipboard.writeText('GOHAN2000');button.textContent='コピー済み ✓';message.textContent='コピーしました。注文画面でコードを入力してください。';event('coupon_copy',{code:'GOHAN2000'})}catch(e){input.focus();input.select();input.setSelectionRange(0,input.value.length);message.textContent='コードを選択しました。長押し、またはコピー操作で取得してください。'}}
function cta(){enterScreen('cta');progress(2);const won=couponEarned;content.innerHTML=`<section class="sale-screen"><p class="sale-kicker">お米はそのまま。炊き方で糖質対策。</p><h1>好きなごはんを、<br><em>もっと気軽に。</em></h1><div class="sale-product"><div class="sale-photo"><img src="data:image/png;base64," alt="LOCABO:V ブラック・ホワイト"></div><div class="sale-brand"><strong>LOCABO:V</strong><span>糖質カット炊飯器 · 360°IH</span></div></div><div class="sale-offer"><div class="sale-discount"><strong>64%OFF</strong><span>メーカー希望小売価格から</span></div><div class="sale-history"><span><small>メーカー希望小売価格</small><s>55,000円</s></span><i aria-hidden="true">→</i><span><small>特別価格</small><b>19,800円</b></span></div>${won?'<p class="sale-bonus">クリア特典で、さらに <strong>2,000円OFF</strong></p>':''}<div class="sale-total"><span>${won?'クーポン適用後':'当ページ限定特別価格'}</span><p><strong>${won?'17,800':'19,800'}</strong><b>円</b><small>（税込）</small></p></div><p class="sale-assurance"><span class="assurance-item">送料無料</span><span>／</span><span class="assurance-item">1年間のメーカー保証</span></p></div>${won?'<div class="sale-code"><label for="coupon-code">クーポンコード</label><div class="sale-code-entry"><input id="coupon-code" value="GOHAN2000" readonly aria-label="クーポンコード GOHAN2000"><button id="copy-coupon">コピー</button></div><p id="copy-status" role="status" aria-live="polite">注文画面でコードを入力してください。</p></div>':''}<a class="sale-buy" id="purchase" href="${destination()}">${won?'クーポンを使って購入する':'特別価格で購入する'}<span aria-hidden="true">→</span></a><p class="sale-footnote">価格は税込。カラー選択・販売条件は商品ページで。</p><div class="sale-secondary"><button id="relearn">仕組みを見る</button><button id="replay">${won?'もう一度遊ぶ':'再チャレンジで2,000円OFFをねらう'}</button></div></section>`;document.getElementById('replay').onclick=()=>{if(phase==='cta'&&ready())start()};document.getElementById('relearn').onclick=()=>{if(phase==='cta'&&ready())explain(0)};if(won)document.getElementById('copy-coupon').onclick=copyCoupon;document.getElementById('purchase').onclick=e=>{if(phase!=='cta'||!ready()){e.preventDefault();return}event('cta_click',{moves,assisted,coupon:won})};event('cta_view',{coupon:won})}
function togglePause(force){if(['cta','explain','result','reward'].includes(phase))return;paused=force??!paused;document.getElementById('pauseLayer').hidden=!paused;document.querySelector('.app')?.classList.toggle('paused',paused);if(paused)document.getElementById('resume').focus()}
document.getElementById('pause').onclick=()=>togglePause();document.getElementById('resume').onclick=()=>togglePause(false);document.addEventListener('visibilitychange',()=>{if(document.hidden&&!['cta','explain','result','reward'].includes(phase))togglePause(true);last=performance.now()});
function advance(dt){if(paused||document.hidden||['cta','result'].includes(phase))return;if(phase==='intro'){left-=dt;const el=document.getElementById('count');if(el)el.textContent=Math.max(1,Math.ceil(left));if(left<=0)begin()}else if(['playing','assist'].includes(phase)){idle+=dt;if(started){elapsed+=dt;if(phase==='playing'){left=Math.max(0,left-dt);document.getElementById('timer').textContent='残り'+Math.ceil(left)+'秒';document.getElementById('timer').classList.toggle('urgent',left<6);if(left<=0)timeout();}}if(idle>4&&hintIndex<0)showHint();}else if(phase==='flow'){left-=dt;if(left<=0)result()}else if(phase==='reward'){left-=dt;if(left<=0)explain(0)}else if(phase==='explain'){left-=dt;const bar=document.getElementById('story-time');if(bar)bar.style.transform=`scaleX(${Math.max(0,left/6.5)})`;if(left<=0)step<2?explain(step+1):cta()}}
function tick(now){const dt=Math.max(0,(now-last)/1000);last=now;advance(dt);requestAnimationFrame(tick)}
function state(){return {phase,moves,remaining:Math.max(0,Math.ceil(left)),paused,started,hintIndex,board:board.slice(),connected:trace(),solved:solved(),assisted,couponEarned,roundWon}}
if(couponEarned)cta();else start();requestAnimationFrame(tick);

}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bootLocaboWaterPuzzle,{once:true});
else bootLocaboWaterPuzzle();
})();